\node[circle,draw=red,fill=white,thick,inner sep=2pt] at (1,0.5) {}; 

\draw[blue, line width=0.5mm,- >] (1,0) -- (2.5,0);
\node[circle,draw=blue,fill=white,thick,inner sep=2pt] at (1,0) {};

\end{tikzpicture}
\end{document}

